{"command": "cd /workspace && cat > work/composer.py << 'PYEOF'
import json

# ---------- note helpers ----------
PC={'C':0,'C#':1,'DB':1,'D':2,'D#':3,'EB':3,'E':4,'F':5,'F#':6,'GB':6,
    'G':7,'G#':8,'AB':8,'A':9,'A#':10,'BB':10,'B':11}
def nn(name):
    if name is None: return None
    if name=='off': return 97
    s=name.strip().upper()
    # split pitch class and octave (octave may be last char, possibly negative not needed)
    i=1
    if len(s)>1 and s[1] in '#B': i=2
    pcs=s[:i]; octv=int(s[i:])
    return 1+octv*12+PC[pcs]
def tr(name,semi):
    v=nn(name); 
    return v+semi if v is not None else None

# ---------- instrument / channel map ----------
LEAD,BASS,ARPL,PAD,KICK,SNARE,HAT,OHAT,LEAD2,SUB,CLAP,CRASH,ARPR,PADL,PADR=range(1,16)
CH_KICK,CH_SNARE,CH_HAT,CH_PERC,CH_BASS,CH_SUB,CH_LEAD,CH_LEAD2,CH_ARP1,CH_ARP2,CH_PADA,CH_PADB=range(12)

# ---------- chord table ----------
CH={
 'Am':{'pad':'A3','q':0x37,'bass':'A2','arp':['A4','C5','E5','A5']},
 'F' :{'pad':'F3','q':0x47,'bass':'F2','arp':['F4','A4','C5','F5']},
 'C' :{'pad':'C4','q':0x47,'bass':'C2','arp':['C5','E5','G5','C6']},
 'G' :{'pad':'G3','q':0x47,'bass':'G2','arp':['G4','B4','D5','G5']},
 'Dm':{'pad':'D3','q':0x37,'bass':'D2','arp':['D4','F4','A4','D5']},
 'E' :{'pad':'E3','q':0x47,'bass':'E2','arp':['E4','G#4','B4','E5']},
}
A_CHORDS=['Am','F','C','G']
B_CHORDS=['Dm','F','C','E']

# ---------- cell store ----------
cells={}  # (pat,row,ch) -> dict
def setc(pat,row,ch,note=None,inst=None,vol=None,eff=None,par=None):
    d={'pattern':pat,'row':row,'channel':ch}
    if note is not None: d['note']=note if isinstance(note,int) else nn(note)
    if inst is not None: d['instrument']=inst
    if vol is not None: d['volume']=vol
    if eff is not None: d['effect']=eff
    if par is not None: d['effect_param']=par
    cells[(pat,row,ch)]=d

# ---------- element generators ----------
def bars_chords(chords):
    # returns list of 64 chord names (one per row), chords is 4 names
    out=[]
    for c in chords:
        out+=[c]*16
    return out

def place_melody(pat,ch,inst,mel,volmap=None,vib=False):
    # mel: dict row->note name or 'off'
    rows=sorted(mel.keys())
    for idx,r in enumerate(rows):
        note=mel[r]
        vol = volmap.get(r,None) if volmap else None
        if note=='off':
            setc(pat,r,ch,note=97)
        else:
            setc(pat,r,ch,note=note,inst=inst,vol=(vol if vol is not None else 50))
            if vib:
                nxt=rows[idx+1] if idx+1<len(rows) else r+4
                for rr in range(r+1,min(nxt,64)):
                    setc(pat,rr,ch,eff=4,par=0x00)  # continue vibrato
                setc(pat,r,ch,note=note,inst=inst,vol=(vol if vol is not None else 50),eff=4,par=0x24)

def place_pad(pat,chords):
    cr=bars_chords(chords)
    for r in range(64):
        c=cr[r]; q=CH[c]['q']
        if r%16==0:
            setc(pat,r,CH_PADA,note=CH[c]['pad'],inst=PADL,vol=30,eff=0,par=q)
            setc(pat,r,CH_PADB,note=CH[c]['pad'],inst=PADR,vol=30,eff=0,par=q)
        else:
            setc(pat,r,CH_PADA,eff=0,par=q)
            setc(pat,r,CH_PADB,eff=0,par=q)

def place_arp(pat,chords,vol=40,oct2=0,patt1=(0,1,2,3),patt2=(2,3,0,1)):
    cr=bars_chords(chords)
    for r in range(64):
        c=cr[r]; tones=CH[c]['arp']
        i1=patt1[r%4]; i2=patt2[r%4]
        setc(pat,r,CH_ARP1,note=tones[i1],inst=ARPL,vol=vol,eff=10,par=8)
        n2=tr(tones[i2],oct2)
        setc(pat,r,CH_ARP2,note=n2,inst=ARPR,vol=max(24,vol-8),eff=10,par=8)

def place_bass(pat,chords,riff,accent=(0,8),sub=False):
    cr=bars_chords(chords)
    for bar in range(4):
        c=cr[bar*16]; root=CH[c]['bass']
        for step,off in riff.items():
            r=bar*16+step
            vol=60 if step in accent else 46
            setc(pat,r,CH_BASS,note=tr(root,off),inst=BASS,vol=vol)
        if sub:
            setc(pat,bar*16,CH_SUB,note=root,inst=SUB,vol=34)
            setc(pat,bar*16+8,CH_SUB,note=root,inst=SUB,vol=30)

def place_drums(pat,kick,snare,hat,ohat,clap=None,rng=range(4)):
    for bar in rng:
        base=bar*16
        for s,v in kick.items(): setc(pat,base+s,CH_KICK,note='C-4',inst=KICK,vol=v)
        for s,v in snare.items(): setc(pat,base+s,CH_SNARE,note='C-4',inst=SNARE,vol=v)
        for s,v in hat.items(): setc(pat,base+s,CH_HAT,note='C-4',inst=HAT,vol=v)
        for s,v in ohat.items(): setc(pat,base+s,CH_HAT,note='C-4',inst=OHAT,vol=v)
        if clap:
            for s,v in clap.items(): setc(pat,base+s,CH_SNARE,note='C-4',inst=CLAP,vol=v)

def crash_at(pat,row,vol=40):
    setc(pat,row,CH_PERC,note='C-4',inst=CRASH,vol=vol)

# ---------- drum dictionaries ----------
K_MAIN={0:64,6:32,8:58,14:34}
S_MAIN={4:56,12:60}
H_MAIN={0:16,2:30,4:18,6:34,8:16,10:30,12:18}
O_MAIN={14:36}
K_FULL={0:64,3:26,6:30,8:62,11:26,14:34}
S_FULL={4:60,12:62}
H_FULL={0:18,1:12,2:32,3:12,4:20,5:12,6:36,7:12,8:18,9:12,10:32,11:12,12:20,13:12}
O_FULL={6:30,14:38}
CLAP_FULL={4:44,12:46}

BASS_RIFF={0:0,2:0,3:12,6:0,8:0,10:0,11:12,14:0}
BASS_SIMPLE={0:0,8:0}

# ---------- melodies ----------
LEAD_A={0:'A5',4:'C6',6:'B5',8:'A5',12:'E5', 16:'F5',20:'A5',22:'G5',24:'F5',28:'E5',
        32:'E5',36:'G5',38:'E5',40:'C6',44:'G5', 48:'D6',52:'B5',54:'G5',56:'A5',58:'B5',60:'D6'}
LEAD_A2={0:'E6',4:'D6',6:'C6',8:'B5',12:'A5', 16:'A5',20:'C6',24:'A5',28:'G5',
         32:'G5',36:'C6',40:'E6',44:'D6', 48:'B5',52:'D6',56:'B5',58:'A5',60:'G5'}
LEAD_B={0:'F5',2:'A5',4:'D6',8:'A5',12:'F5', 16:'A5',20:'C6',24:'A5',28:'G5',
        32:'E5',36:'G5',40:'C6',44:'G5', 48:'B5',52:'G#5',56:'E5',58:'G#5',60:'B5'}
LEAD_B2={0:'A5',4:'E5',8:'C6',12:'A5', 16:'C6',20:'A5',24:'F5',28:'A5',
         32:'G5',36:'E5',40:'G5',44:'C6', 48:'D6',52:'B5',56:'G5',60:'B5'}

def leadvol(mel): 
    # accent downbeats
    return {r:(54 if r%16 in (0,8) else 46) for r in mel}

def harmony(mel,semi=-12):
    return {r:tr(mel[r],semi) and None for r in mel}  # placeholder

def mel_shift(mel,semi):
    out={}
    for r,n in mel.items():
        if n=='off': out[r]='off'
        else:
            v=nn(n)+semi; out[r]=v
    return out

# ---------- build patterns ----------
def P0():  # intro 1: pad + soft bass
    place_pad(0,A_CHORDS)
    place_bass(0,A_CHORDS,BASS_SIMPLE,accent=(0,),sub=True)
    for bar in range(4): setc(0,bar*16,CH_KICK,note='C-4',inst=KICK,vol=38)
    crash_at(0,0,34)
def P1():  # intro 2: add arp + hats + light kick
    place_pad(1,A_CHORDS)
    place_bass(1,A_CHORDS,BASS_RIFF,sub=True)
    place_arp(1,A_CHORDS,vol=34)
    place_drums(1,{0:58,8:54},{},{2:22,6:26,10:22,14:26},{})
    # pickup fill into P2
    for i,r in enumerate([56,58,60,62]):
        setc(1,r,CH_SNARE,note='C-4',inst=SNARE,vol=30+i*8)
def groove(pat,chords,lead,leadinst=LEAD,vib=True,full=False,climax=False):
    place_pad(pat,chords)
    place_bass(pat,chords,BASS_RIFF,sub=True)
    place_arp(pat,chords,vol=40)
    if full or climax:
        place_drums(pat,K_FULL,S_FULL,H_FULL,O_FULL,clap=(CLAP_FULL if climax else None))
    else:
        place_drums(pat,K_MAIN,S_MAIN,H_MAIN,O_MAIN)
    place_melody(pat,CH_LEAD,leadinst,lead,volmap=leadvol(lead),vib=vib)
    if climax:
        # harmony an octave below with lead2
        place_melody(pat,CH_LEAD2,LEAD2,mel_shift(lead,-12),
                     volmap={r:34 for r in lead},vib=False)
def P2(): groove(2,A_CHORDS,LEAD_A)
def P3():
    groove(3,A_CHORDS,LEAD_A2)
    # end fill
    for i,r in enumerate([58,60,62]): setc(3,r,CH_SNARE,note='C-4',inst=SNARE,vol=40+i*6)
def P4(): groove(4,B_CHORDS,LEAD_B)
def P5():
    groove(5,A_CHORDS,LEAD_B2)
    for i,r in enumerate([60,62]): setc(5,r,CH_SNARE,note='C-4',inst=SNARE,vol=44+i*8)
def P8():
    groove(8,A_CHORDS,LEAD_A,full=True,climax=True); crash_at(8,0,42)
def P9():
    groove(9,A_CHORDS,LEAD_A2,full=True,climax=True); crash_at(9,0,40)
    for i,r in enumerate([56,58,60,62]): setc(9,r,CH_SNARE,note='C-4',inst=SNARE,vol=34+i*7)
def P6():  # break: pad+arp, sparse
    place_pad(6,A_CHORDS)
    place_arp(6,A_CHORDS,vol=36)
    place_bass(6,A_CHORDS,BASS_SIMPLE,accent=(0,),sub=True)
    for bar in range(4):
        setc(6,bar*16,CH_KICK,note='C-4',inst=KICK,vol=40)
        setc(6,bar*16+2,CH_HAT,note='C-4',inst=HAT,vol=18)
